          '"First, raw materials are collected from suppliers across the region. They are then transported to the main processing facility. Upon arrival, the materials are sorted and categorised according to type. Subsequently, they are heated and mixed to form a uniform compound. Once cooled, the mixture is moulded into the required shape. Finally, each unit undergoes quality inspection before being packaged for distribution."',
