         ('research consistently shows','研究一贯表明 — research consistently shows that'),
         ('it is widely acknowledged','普遍认为 — it is widely acknowledged that'),
         ('the evidence suggests','证据表明 — the evidence suggests that investment...'),
         ('this underscores the need for','这强调了...的必要性 — underscores the need for reform'),
         ('far outweigh','远超 — the benefits far outweigh the costs'),
