        '引言：The line graph illustrates the proportion of households with internet connectivity in four countries — Japan, South Korea, Germany, and Brazil — across a twenty-year period.\n\nOverall: Overall, internet penetration increased in all four nations over the period. South Korea consistently recorded the highest access rates, while Brazil demonstrated the most dramatic growth, rising from a very low base to reach comparable levels with the European nation by 2020.\n\n主体段1（亚洲）：South Korea led all four countries throughout the period, with household internet access climbing from 45% in 2000 to 95% by 2020. Japan followed a similar upward trajectory, rising from 34% to 91%, though it remained slightly below South Korean figures at each measured point.\n\n主体段2（欧洲+拉美）：Germany also registered consistent growth, increasing from 30% to 88% over the two decades. The most notable change, however, occurred in Brazil, where internet access rose nearly fifteenfold, from just 5% in 2000 to 74% in 2020, narrowing the gap with Germany considerably by the end of the period.',
